887	// 校验请求中的资源标识：去重、检查存在性；返回按标识排序的集合
888	function resolveResourceIds(store: Store, rawIds: string[]): string[] {
889	  const problems: string[] = [];
890	  const seen = new Set<string>();
891	  const dupes: string[] = [];
892	  for (const id of rawIds) {
893	    if (seen.has(id)) {
894	      if (!dupes.includes(id)) dupes.push(id);
895	    }
896	    seen.add(id);
897	  }
898	  if (dupes.length > 0) problems.push(`资源重复指定: ${dupes.join('、')}`);
899	
900	  const unknown = [...seen].filter((id) => !store.resources.some((r) => r.id === id)).sort();
901	  if (unknown.length > 0) problems.push(`未知资源标识: ${unknown.join('、')}`);
902	
903	  if (problems.length > 0) throw new BizError(problems.join('\n'));
904	  return [...seen].sort();
905	}
