907	function openSegmentsOf(r: ResourceRec): Array<[number, number]> {
908	  return mergeIntervals(
909	    r.open.map(
910	      ([s, e]) =>
911	        [parseDateTime(s, '开放区间开始时间'), parseDateTime(e, '开放区间结束时间')] as [number, number],
