916	// 从连续区间中扣除一段停用（左闭右开），返回剩余连续区间
917	function subtractSegments(
918	  segments: Array<[number, number]>,
919	  cuts: Array<[number, number]>,
920	): Array<[number, number]> {
921	  let result = segments;
922	  for (const [cs, ce] of mergeIntervals(cuts)) {
923	    const next: Array<[number, number]> = [];
924	    for (const [s, e] of result) {
925	      if (ce <= s || e <= cs) {
926	        next.push([s, e]);
927	        continue;
928	      }
929	      if (s < cs) next.push([s, cs]);
930	      if (ce < e) next.push([ce, e]);
931	    }
932	    result = next;
933	  }
934	  return result;
935	}
