938	function activeClosuresOf(store: Store, resourceId: string): ClosureRec[] {
939	  return store.closures
940	    .filter((c) => c.resourceId === resourceId && c.status === 'active')
941	    .sort(
942	      (a, b) =>
943	        parseDateTime(a.start, '停用开始时间') - parseDateTime(b.start, '停用开始时间') ||
944	        a.id.localeCompare(b.id),
