948	// 实际可用时间：原开放区间合并后，扣除该资源全部有效停用区间的并集（原开放记录保留）
949	function availableSegmentsOf(store: Store, r: ResourceRec): Array<[number, number]> {
950	  const cuts = activeClosuresOf(store, r.id).map(
951	    (c) =>
952	      [parseDateTime(c.start, '停用开始时间'), parseDateTime(c.end, '停用结束时间')] as [number, number],
953	  );
954	  return subtractSegments(openSegmentsOf(r), cuts);
955	}
