963	// 找出实际可用时间（开放扣除有效停用）不能完整覆盖 [startMin, endMin) 的资源
964	function findCoverageGaps(
965	  store: Store,
966	  ids: string[],
967	  startMin: number,
968	  endMin: number,
969	): CoverageGap[] {
970	  const gaps: CoverageGap[] = [];
971	  for (const id of ids) {
972	    const r = store.resources.find((x) => x.id === id)!;
973	    if (isFullyCovered(availableSegmentsOf(store, r), startMin, endMin)) continue;
974	    const closures = activeClosuresOf(store, id).filter((c) => {
975	      const cs = parseDateTime(c.start, '停用开始时间');
976	      const ce = parseDateTime(c.end, '停用结束时间');
977	      return cs < endMin && startMin < ce;
978	    });
979	    gaps.push({id, r, closures});
980	  }
981	  return gaps;
982	}
