984	// 开放不足资源的统一展示：资源行 + 相关有效停用（标识与时间）
985	function gapLines(gaps: CoverageGap[], indent: string): string[] {
986	  const lines: string[] = [];
987	  for (const g of gaps) {
988	    lines.push(`${indent}- ${g.id}（${g.r.name}）`);
989	    for (const c of g.closures) {
990	      lines.push(`${indent}  相关有效停用: ${c.id}（${c.start} → ${c.end}）`);
991	    }
992	  }
993	  return lines;
994	}
