996	// 校验每个资源的实际可用时间都能完整覆盖 [startMin, endMin)
997	function assertOpenCoverage(store: Store, ids: string[], startMin: number, endMin: number): void {
998	  const failing = findCoverageGaps(store, ids, startMin, endMin);
999	  if (failing.length > 0) {
1000	    throw new BizError(
1001	      '开放时间不足，以下资源的实际可用时间（开放区间扣除有效停用）不能完整覆盖预约区间：\n' +
1002	        gapLines(failing, '').join('\n'),
1003	    );
1004	  }
