1012	// 与“已预约”记录求冲突：共同资源且时间重叠（左闭右开）；可排除自身
1013	function findConflicts(
1014	  store: Store,
1015	  ids: string[],
1016	  startMin: number,
1017	  endMin: number,
1018	  excludeBookingId?: string,
1019	): Conflict[] {
1020	  const wanted = new Set(ids);
1021	  const conflicts: Conflict[] = [];
1022	  for (const b of store.bookings) {
1023	    if (b.status !== 'active') continue;
1024	    if (excludeBookingId !== undefined && b.id === excludeBookingId) continue;
1025	    const bStart = parseDateTime(b.start, '预约开始时间');
1026	    const bEnd = parseDateTime(b.end, '预约结束时间');
1027	    const overlap = bStart < endMin && startMin < bEnd;
1028	    if (!overlap) continue;
1029	    const shared = b.resourceIds.filter((id) => wanted.has(id)).sort();
1030	    if (shared.length > 0) conflicts.push({booking: b, shared});
1031	  }
1032	  conflicts.sort((a, b) => a.booking.id.localeCompare(b.booking.id));
1033	  return conflicts;
1034	}
