1036	function assertNoConflicts(conflicts: Conflict[], store: Store): void {
1037	  if (conflicts.length === 0) return;
1038	  const lines = conflicts.map(
1039	    (c) => `- ${c.booking.id}：共同资源 ${formatResourceIds(store, c.shared)}`,
1040	  );
1041	  throw new BizError(`预约与以下预约冲突（共同资源时间重叠）：\n${lines.join('\n')}`);
1042	}
