1111	function splitGlobalArgs(argv: string[]): GlobalArgs {
1112	  const result: GlobalArgs = {dataFile: DEFAULT_DATA_FILE, help: false, rest: []};
1113	  for (let i = 0; i < argv.length; i++) {
1114	    const a = argv[i];
1115	    if (a === '-h' || a === '--help') {
1116	      result.help = true;
1117	    } else if (a === '--data') {
1118	      const v = argv[++i];
1119	      if (v === undefined) throw new UsageError('选项 --data 缺少数据文件路径');
1120	      result.dataFile = v;
1121	    } else if (a.startsWith('--data=')) {
1122	      result.dataFile = a.slice('--data='.length);
1123	      if (result.dataFile === '') throw new UsageError('选项 --data 缺少数据文件路径');
1124	    } else {
1125	      result.rest.push(a);
1126	    }
1127	  }
1128	  return result;
1129	}
