1131	interface ParsedFlags {
1132	  values: Map<string, string[]>;
1133	  positionals: string[];
1134	}
1135	
1136	// 子命令选项解析：allowed 中列出的选项均需带值；multi 中的选项可重复
1137	function parseFlags(args: string[], allowed: string[], multi: string[] = []): ParsedFlags {
1138	  const allowedSet = new Set(allowed);
1139	  const multiSet = new Set(multi);
1140	  const values = new Map<string, string[]>();
1141	  const positionals: string[] = [];
1142	
1143	  const takeValue = (key: string, inline: string | undefined, index: number): [string, number] => {
1144	    if (inline !== undefined) return [inline, index];
1145	    const v = args[index + 1];
1146	    if (v === undefined || v.startsWith('-')) {
1147	      throw new UsageError(`选项 --${key} 缺少值`);
1148	    }
1149	    return [v, index + 1];
1150	  };
1151	
1152	  for (let i = 0; i < args.length; i++) {
1153	    const a = args[i];
1154	    if (a.startsWith('--')) {
1155	      let key: string;
1156	      let inline: string | undefined;
1157	      const eq = a.indexOf('=');
1158	      if (eq >= 0) {
1159	        key = a.slice(2, eq);
1160	        inline = a.slice(eq + 1);
1161	      } else {
1162	        key = a.slice(2);
1163	      }
1164	      if (!allowedSet.has(key)) throw new UsageError(`未知选项: --${key}`);
1165	      let v: string;
1166	      [v, i] = takeValue(key, inline, i);
1167	      if (v === '') throw new UsageError(`选项 --${key} 的值不能为空`);
1168	      if (!multiSet.has(key) && values.has(key)) {
1169	        throw new UsageError(`选项 --${key} 只能指定一次`);
1170	      }
1171	      const list = values.get(key) ?? [];
1172	      list.push(v);
1173	      values.set(key, list);
1174	    } else if (a.startsWith('-') && a !== '-') {
1175	      throw new UsageError(`未知参数: ${a}`);
1176	    } else {
1177	      positionals.push(a);
1178	    }
1179	  }
1180	  return {values, positionals};
1181	}
1182	
1183	function requireFlag(values: Map<string, string[]>, key: string): string {
1184	  const v = values.get(key)?.[0];
1185	  if (v === undefined) throw new UsageError(`缺少必需选项 --${key}`);
1186	  return v;
1187	}
