1245	async function cmdCreateBooking(args: string[]): Promise<void> {
1246	  const {values, positionals} = parseFlags(args, ['resource', 'start', 'end'], ['resource']);
1247	  if (positionals.length > 0) throw new UsageError(`create-booking 不接受位置参数: ${positionals.join(' ')}`);
1248	
1249	  const resourceArgs = values.get('resource');
1250	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
1251	  const startRaw = requireFlag(values, 'start');
1252	  const endRaw = requireFlag(values, 'end');
