1357	// 清单结构（与数据文件无关的纯类型校验）；返回逐项原始记录
1358	function parseManifestShape(raw: unknown, file: string): Array<Record<string, unknown>> {
1359	  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
1360	    throw new BizError(`改期清单 ${file} 内容非法：顶层必须是对象，形如 {"items": [...]}`);
1361	  }
1362	  const o = raw as Record<string, unknown>;
1363	  for (const k of Object.keys(o)) {
1364	    if (k !== 'items') throw new BizError(`改期清单 ${file} 内容非法：存在未知字段 “${k}”，只允许 items`);
1365	  }
1366	  if (!Array.isArray(o.items)) {
1367	    throw new BizError(`改期清单 ${file} 内容非法：items 必须是非空数组`);
1368	  }
1369	  const items = o.items as unknown[];
1370	  if (items.length === 0) throw new BizError(`改期清单 ${file} 为空：items 至少包含一项改期安排`);
1371	
1372	  const problems: string[] = [];
1373	  const records: Array<Record<string, unknown> | null> = [];
1374	  items.forEach((it, idx) => {
1375	    const at = `第 ${idx + 1} 项`;
1376	    if (typeof it !== 'object' || it === null || Array.isArray(it)) {
1377	      problems.push(`${at} 必须是对象`);
1378	      records.push(null);
1379	      return;
1380	    }
1381	    const rec = it as Record<string, unknown>;
1382	    for (const k of Object.keys(rec)) {
1383	      if (k !== 'bookingId' && k !== 'start' && k !== 'end' && k !== 'resourceIds') {
1384	        problems.push(`${at} 存在未知字段 “${k}”（只允许 bookingId、start、end、resourceIds）`);
1385	      }
1386	    }
1387	    if (typeof rec.bookingId !== 'string' || rec.bookingId === '') {
1388	      problems.push(`${at} 的 bookingId 必须是非空字符串`);
1389	    }
1390	    if (typeof rec.start !== 'string' || rec.start === '') {
1391	      problems.push(`${at} 的 start 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1392	    }
1393	    if (typeof rec.end !== 'string' || rec.end === '') {
1394	      problems.push(`${at} 的 end 必须是 YYYY-MM-DDTHH:mm 形式的非空字符串`);
1395	    }
1396	    if (!Array.isArray(rec.resourceIds)) {
1397	      problems.push(`${at} 的 resourceIds 必须是非空数组（完整目标资源集合，整体替换原集合）`);
1398	    } else {
1399	      if (rec.resourceIds.length === 0) problems.push(`${at} 的 resourceIds 不能为空：资源集合整体替换，至少一个资源`);
1400	      rec.resourceIds.forEach((rid, j) => {
1401	        if (typeof rid !== 'string' || rid === '') {
1402	          problems.push(`${at}.resourceIds[${j}] 必须是非空资源标识字符串`);
1403	        }
1404	      });
1405	    }
1406	    records.push(rec);
1407	  });
1408	  if (problems.length > 0) {
1409	    throw new BizError(`改期清单 ${file} 内容非法，整批拒绝：\n${problems.map((p) => `- ${p}`).join('\n')}`);
1410	  }
1411	  return records as Array<Record<string, unknown>>;
1412	}
