1881	// 按周展开系列：每项相对前一项将起止时间同时后移 7 个营业地日历日，
1882	// 时刻与跨日长度保持不变。任何一项超出四位年份范围即整体拒绝。
1883	function planWeeklyMembers(startMin: number, endMin: number, count: number): PlannedMember[] {
1884	  const members: PlannedMember[] = [];
1885	  for (let i = 0; i < count; i++) {
1886	    const s = startMin + i * 7 * 1440;
1887	    const e = endMin + i * 7 * 1440;
1888	    const startRaw = formatDateTime(s);
1889	    const endRaw = formatDateTime(e);
1890	    if (startRaw === null || endRaw === null) {
1891	      const nth = i + 1;
1892	      throw new BizError(
1893	        `系列第 ${nth} 项（约第 ${nth} 周）的时间超出四位年份范围（${MIN_YEAR}-${MAX_YEAR}），无法创建：` +
1894	          '请缩短次数或改选更早的首项时间',
1895	      );
1896	    }
1897	    members.push({startRaw, endRaw, startMin: s, endMin: e});
1898	  }
1899	  return members;
1900	}
