1922	  // 先展开全部成员时间（含跨月、闰日、跨年、年份范围校验）
1923	  const members = planWeeklyMembers(startMin, endMin, count);
1924	
1925	  // 以展开后的全部成员为目标做统一批次校验（无写入副作用）：
1926	  // 开放覆盖、与既有有效预约冲突、与系列内其他成员冲突
1927	  const targets = members.map((m) => ({startMin: m.startMin, endMin: m.endMin, resourceIds: ids}));
1928	  const failures = validateBatchTargets(store, targets);
