1941	        for (const c of f.external) {
1942	          lines.push(
1943	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
1944	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
1945	          );
1946	        }
1947	      }
1948	      if (f.internal.length > 0) {
