1951	          const o = members[x.otherIndex];
1952	          lines.push(
1953	            `    - 第 ${x.otherIndex + 1} 项（${o.startRaw} → ${o.endRaw}）：双方时间重叠`,
1954	          );
1955	        }
1956	      }
1957	      return lines.join('\n');
1958	    });
1959	    throw new BizError(
1960	      `系列创建失败：共 ${failures.length} 项不满足条件（按发生顺序），整批未创建：\n${blocks.join('\n')}`,
