2283	function flexBusySegments(
2284	  store: Store,
2285	  ids: string[],
2286	  wStart: number,
2287	  wEnd: number,
2288	): Array<[number, number]> {
2289	  const wanted = new Set(ids);
2290	  const cuts: Array<[number, number]> = [];
2291	  for (const b of store.bookings) {
2292	    if (b.status !== 'active') continue;
2293	    if (!b.resourceIds.some((id) => wanted.has(id))) continue;
2294	    const bStart = parseDateTime(b.start, '预约开始时间');
2295	    const bEnd = parseDateTime(b.end, '预约结束时间');
2296	    const a = Math.max(bStart, wStart);
2297	    const c = Math.min(bEnd, wEnd);
2298	    if (a < c) cuts.push([a, c]);
2299	  }
2300	  return mergeIntervals(cuts);
2301	}
