2591	// iCalendar 导入（import-ical）
2592	// 读取 UTF-8 的 VCALENDAR（VERSION:2.0，至少一个独立 VEVENT），为新事件各创建
2593	// 一项普通预约（不加入系列、不自动处理候补），全部使用命令行给定的同一资源集合。
2594	// UID 在同一数据文件中永久关联首次生成的预约；相同 UID 且时间、资源集合与首次
2595	// 导入一致为重放（返回原预约当前安排与状态，不做任何改动），不一致则整批拒绝。
2596	// ---------------------------------------------------------------------------
2597	
2598	// 一个解析完成的 VEVENT（时间已换算为营业地分钟数与 YYYY-MM-DDTHH:mm 文本）
2599	interface IcalEvent {
2600	  uid: string; // 解码后的 UID（区分大小写）
2601	  startRaw: string;
2602	  endRaw: string;
2603	  startMin: number;
2604	  endMin: number;
2605	}
2606	
2607	// 标准折行展开：以空格或制表符开头的行是上一行的延续（去掉首个空白字符拼接）。
2608	// 同时支持 CRLF 与 LF 行尾；空行忽略（文件末尾换行自然被吞掉）。
2609	function unfoldIcalLines(text: string, bad: (reason: string) => never): string[] {
2610	  const lines: string[] = [];
2611	  for (const raw of text.split(/\r\n|\n/)) {
2612	    if (raw === '') continue;
2613	    if (raw.startsWith(' ') || raw.startsWith('\t')) {
2614	      if (lines.length === 0) bad('文件以折行续行开头，缺少被延续的内容行');
2615	      lines[lines.length - 1] += raw.slice(1);
2616	    } else {
2617	      lines.push(raw);
2618	    }
2619	  }
2620	  return lines;
2621	}
2622	
2623	// 拆分内容行为 属性名;参数:值；属性名忽略大小写（统一转大写返回）
2624	function parseContentLine(
2625	  line: string,
2626	  bad: (reason: string) => never,
2627	): {name: string; params: string[]; value: string} {
2628	  const colon = line.indexOf(':');
2629	  if (colon < 0) bad(`内容行缺少 “:”: “${line}”`);
2630	  const head = line.slice(0, colon);
2631	  const value = line.slice(colon + 1);
2632	  const segs = head.split(';');
2633	  if (!/^[A-Za-z0-9-]+$/.test(segs[0])) bad(`属性名非法: “${segs[0]}”`);
2634	  return {name: segs[0].toUpperCase(), params: segs.slice(1), value};
2635	}
