2637	// UID 文本转义解码：\\ → \，\n/\N → 换行，\, → ,，\; → ;；其余反斜杠序列原样保留。
2638	// 解码后再比较，因此同一 UID 的不同转义写法视为相同。
2639	function unescapeIcalText(value: string): string {
2640	  return value.replace(/\\(\\|[nN]|,|;)/g, (_all, ch: string) =>
2641	    ch === 'n' || ch === 'N' ? '\n' : ch,
2642	  );
2643	}
