2671	// DTSTART/DTEND 的参数：仅允许显式的 VALUE=DATE-TIME（即默认浮动时间）；
2672	// 全天（VALUE=DATE）、时区（TZID）及其他参数一律拒绝
2673	function assertFloatingDateTimeParams(
2674	  params: string[],
2675	  label: string,
2676	  bad: (reason: string) => never,
2677	): void {
2678	  for (const p of params) {
2679	    const upper = p.toUpperCase();
2680	    if (upper === 'VALUE=DATE-TIME') continue;
2681	    if (upper === 'VALUE=DATE') bad(`${label}不支持全天事件（VALUE=DATE）`);
2682	    if (upper.startsWith('TZID=')) bad(`${label}不支持时区时间（TZID），仅接受浮动时间`);
2683	    bad(`${label}携带不支持的参数 “${p}”，仅接受浮动时间 YYYYMMDDTHHmmss`);
2684	  }
2685	}
