2824	async function cmdImportIcal(args: string[]): Promise<void> {
2825	  const {values, positionals} = parseFlags(args, ['resource'], ['resource']);
2826	  if (positionals.length !== 1) {
2827	    throw new UsageError('用法: import-ical <iCalendar 文件> --resource <标识> [--resource <标识> ...]');
2828	  }
2829	  const resourceArgs = values.get('resource');
2830	  if (!resourceArgs || resourceArgs.length === 0) throw new UsageError('至少需要一个 --resource');
2831	  const icalFile = positionals[0];
2832	
2833	  const file = activeDataFile;
2834	  const store = await loadStore(file);
2835	  // 新事件统一使用该资源集合（至少一个不同的已登记资源，按标识排序）
2836	  const ids = resolveResourceIds(store, resourceArgs);
2837	
2838	  // 输入文件不可读、结构非法均整批失败，不触碰数据文件
2839	  let text: string;
2840	  try {
2841	    text = await readFile(icalFile, 'utf8');
2842	  } catch (err) {
2843	    throw new BizError(`无法读取 iCalendar 文件 ${icalFile}: ${(err as Error).message}`);
2844	  }
2845	  const events = parseIcalFile(text, icalFile);
2846	
2847	  // 区分重放与新增：UID 命中既有导入身份即重放候选；
2848	  // 时间与资源集合（顺序无关）须与首次导入快照一致，否则整批拒绝
2849	  const importByUid = new Map(store.imports.map((r) => [r.uid, r]));
2850	  interface ImportItem {
2851	    ev: IcalEvent;
2852	    index: number; // 0 基，按文件顺序
2853	    replay?: ImportRec;
2854	  }
2855	  const mismatches: string[] = [];
2856	  const items: ImportItem[] = events.map((ev, index) => {
2857	    const rec = importByUid.get(ev.uid);
2858	    if (rec === undefined) return {ev, index};
2859	    const sameTime = rec.start === ev.startRaw && rec.end === ev.endRaw;
2860	    const sameResources =
2861	      rec.resourceIds.length === ids.length && rec.resourceIds.every((x, j) => x === ids[j]);
2862	    if (!sameTime || !sameResources) {
2863	      mismatches.push(
2864	        `第 ${index + 1} 项 UID “${ev.uid}”：首次导入为 ${rec.start} → ${rec.end}` +
2865	          `（资源 ${rec.resourceIds.join('、')}），本次为 ${ev.startRaw} → ${ev.endRaw}` +
2866	          `（资源 ${ids.join('、')}）`,
2867	      );
2868	    }
2869	    return {ev, index, replay: rec};
2870	  });
2871	  if (mismatches.length > 0) {
2872	    throw new BizError(
2873	      `iCalendar 导入被拒绝：${mismatches.length} 个 UID 的时间或资源集合与首次导入不一致` +
2874	        '（相同 UID 不会覆盖本地安排，整批未导入）：\n' +
2875	        mismatches.map((m) => `- ${m}`).join('\n'),
2876	    );
2877	  }
2878	
2879	  // 仅以新 UID 事件为目标做统一批次校验（无写入副作用）；
2880	  // 重放项关联的旧预约本就在 store.bookings 中，按当前状态与安排自然参与
2881	  // 既有占用（已取消不占用，改期后按新安排占用），不用首次导入快照代替现状
2882	  const newItems = items.filter((it) => it.replay === undefined);
2883	  const targets = newItems.map((it) => ({
2884	    startMin: it.ev.startMin,
2885	    endMin: it.ev.endMin,
2886	    resourceIds: ids,
2887	  }));
