2889	
2890	  if (failures.length > 0) {
2891	    // 按文件顺序报告全部失败 UID、时间、不足资源（含相关停用）与全部冲突；批内冲突双方互列
2892	    const blocks = failures.map((f) => {
2893	      const item = newItems[f.index];
2894	      const lines = [
2895	        `第 ${item.index + 1} 项 UID “${item.ev.uid}”（${item.ev.startRaw} → ${item.ev.endRaw}）：`,
2896	      ];
2897	      if (f.gaps.length > 0) {
2898	        lines.push('  开放不足资源:');
2899	        lines.push(...gapLines(f.gaps, '    '));
2900	      }
2901	      if (f.external.length > 0) {
2902	        lines.push('  冲突预约:');
2903	        for (const c of f.external) {
2904	          lines.push(
2905	            `    - ${c.booking.id}（${c.booking.start} → ${c.booking.end}）` +
2906	              `：共同资源 ${formatResourceIds(store, c.shared)}`,
2907	          );
2908	        }
2909	      }
2910	      if (f.internal.length > 0) {
2911	        lines.push('  批内冲突:');
2912	        for (const x of f.internal) {
2913	          const o = newItems[x.otherIndex];
2914	          lines.push(
2915	            `    - 第 ${o.index + 1} 项 UID “${o.ev.uid}”` +
2916	              `（${o.ev.startRaw} → ${o.ev.endRaw}）` +
2917	              `：共同资源 ${formatResourceIds(store, x.shared)}`,
2918	          );
2919	        }
2920	      }
2921	      return lines.join('\n');
2922	    });
