2924	      `iCalendar 导入失败：共 ${failures.length} 项新事件不满足条件（按文件顺序），整批未导入：\n${blocks.join('\n')}`,
2925	    );
2926	  }
2927	
2928	  const replayCount = items.length - newItems.length;
2929	  const renderItem = (it: ImportItem, bookingId: string, isNew: boolean): string[] => {
2930	    if (isNew) {
2931	      return [
2932	        `- 第 ${it.index + 1} 项 UID “${it.ev.uid}” → 新预约 ${bookingId}（新增，普通预约，不属于任何系列）`,
2933	        `    时间: ${it.ev.startRaw} → ${it.ev.endRaw}`,
2934	        `    资源: ${formatResourceIds(store, ids)}`,
2935	      ];
2936	    }
2937	    // 重放：返回原预约的当前安排与状态，不做任何改动（已取消/被撤销也不复活）
2938	    const b = store.bookings.find((x) => x.id === bookingId)!;
2939	    const statusLabel = b.status === 'active' ? '已预约' : '已取消';
2940	    return [
2941	      `- 第 ${it.index + 1} 项 UID “${it.ev.uid}” → 预约 ${bookingId}（重放，未做改动）`,
2942	      `    当前状态: ${statusLabel}`,
2943	      `    当前安排: ${b.start} → ${b.end}`,
2944	      `    当前资源: ${formatResourceIds(store, b.resourceIds)}`,
2945	    ];
2946	  };
2947	
2948	  if (newItems.length === 0) {
2949	    // 全为重放：不写文件、不推进任何计数
2950	    console.log(
2951	      `iCalendar 导入完成：共 ${items.length} 项，全部为重放（未写入数据文件，标识计数不变）`,
2952	    );
2953	    for (const it of items) {
2954	      console.log(renderItem(it, it.replay!.bookingId, false).join('\n'));
2955	    }
2956	    return;
2957	  }
2958	
2959	  // 新预约与导入身份一次原子保存后才成功；标识在此刻才生成，任何失败都不推进计数
2960	  const assigned = new Map<ImportItem, string>();
2961	  for (const it of newItems) {
2962	    store.bookingSeq += 1;
2963	    const bookingId = `B${String(store.bookingSeq).padStart(4, '0')}`;
2964	    store.bookings.push({
2965	      id: bookingId,
2966	      resourceIds: ids,
2967	      start: it.ev.startRaw,
2968	      end: it.ev.endRaw,
2969	      status: 'active',
2970	    });
2971	    store.imports.push({
2972	      uid: it.ev.uid,
2973	      bookingId,
2974	      start: it.ev.startRaw,
2975	      end: it.ev.endRaw,
2976	      resourceIds: [...ids],
2977	    });
2978	    assigned.set(it, bookingId);
2979	  }
2980	  store.bookings.sort((a, b) => a.id.localeCompare(b.id));
2981	  store.imports.sort((a, b) => a.uid.localeCompare(b.uid));
2982	  await saveStore(file, store);
2983	
2984	  console.log(`iCalendar 导入完成：共 ${items.length} 项（新增 ${newItems.length} 项，重放 ${replayCount} 项）`);
2985	  for (const it of items) {
2986	    const isNew = it.replay === undefined;
2987	    const bookingId = isNew ? assigned.get(it)! : it.replay!.bookingId;
2988	    console.log(renderItem(it, bookingId, isNew).join('\n'));
2989	  }
2990	}
