  const f = writeIcal(dir, 'a.ics', ical(event('uid-new', '20261012T140000', '20261012T150000')));
  importOk(df, f, ['R0001'], '旧文件直接导入');
  let store = readStore(df);
  assert.equal(store.bookings.length, 2);
  assert.equal(store.imports.length, 1);

