closeEvent changes:

```ts
const closeEvent = (): void => {
  if (curUid === undefined) bad('VEVENT 缺少 UID 属性');
  if (curStart === undefined) ...;
  if (curEnd === undefined) ...;
  if (curEnd.min <= curStart.min) ...;
  if (seenUids.has(curUid)) ...;
  seenUids.add(curUid);
  const ev: IcalEvent = {uid: curUid, startRaw: curStart.raw, endRaw: curEnd.raw, startMin: curStart.min, endMin: curEnd.min};
  if (curRruleCount !== undefined) {
    const count = curRruleCount;
    // 展开全部发生：每项起止同时后移 7 个营业地日历日，保持时刻与跨日长度
    const excludeSet = new Set(curExdates); // 集合去重
    const occurrences: IcalOccurrence[] = [];
    const excludes: string[] = [];
    for (let k = 0; k < count; k++) {
      const sMin = curStart.min + k * 7 * 1440;
      const eMin = curEnd.min + k * 7 * 1440;
      const sRaw = formatDateTime(sMin);
      const eRaw = formatDateTime(eMin);
      if (sRaw === null || eRaw === null) {
        bad(`VEVENT（UID “${curUid}”）按 COUNT=${count} 展开的第 ${k + 1} 次发生越出 ${MIN_YEAR}-${MAX_YEAR} 年范围`);
      }
      if (excludeSet.has(sRaw!)) {
        excludes.push(sRaw!);
      } else {
        occurrences.push({startRaw: sRaw!, endRaw: eRaw!, startMin: sMin, endMin: eMin});
      }
    }
    if (occurrences.length === 0) {
      bad(`VEVENT（UID “${curUid}”）的全部 ${count} 次发生均被 EXDATE 排除`);
    }
    ev.recurrence = {count, excludes, occurrences};
  } else if (curExdates.length > 0) {
    bad(`VEVENT（UID “${curUid}”）含有 EXDATE 但没有 RRULE（排除日期仅用于按周重复事件）`);
  }
  events.push(ev);
  inEvent = false;
  curUid = undefined;
  curStart = undefined;
  curEnd = undefined;
  curRruleCount = undefined;
  curExdates = [];
};
```

Note: excludes built in occurrence order (k ascending) → already sorted chronologically. Good.

