```ts
// 首次导入快照的请求描述（用于不一致诊断）
function describeImportSnapshot(rec: ImportRec): string {
  const base = `${rec.start} → ${rec.end}（资源 ${rec.resourceIds.join('、')}）`;
  if (rec.seriesId === undefined) return `独立事件 ${base}`;
  const ex = rec.excludes!.length > 0 ? `，排除 ${rec.excludes!.join('、')}` : '';
  return `按周重复系列（首项 ${rec.start} → ${rec.end}，共 ${rec.count} 次${ex}；资源 ${rec.resourceIds.join('、')}）`;
}

function describeEventRequest(ev: IcalEvent, ids: string[]): string {
  const base = `${ev.startRaw} → ${ev.endRaw}（资源 ${ids.join('、')}）`;
  if (ev.recurrence === undefined) return `独立事件 ${base}`;
  const ex = ev.recurrence.excludes.length > 0 ? `，排除 ${ev.recurrence.excludes.join('、')}` : '';
  return `按周重复系列（首项 ${ev.startRaw} → ${ev.endRaw}，共 ${ev.recurrence.count} 次${ex}；资源 ${ids.join('、')}）`;
}
